import "core-js/modules/es.array.push.js";
/* eslint-disable */
import CreateProduct from "@/components/CRM/Popups/CreateProduct.vue";
import DeleteProduct from "@/components/CRM/Popups/DeleteProduct.vue";

// import { list_product_details } from "@/graphql/queries.js";
// import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    CreateProduct,
    SnackBar,
    DeleteProduct
  },
  data() {
    return {
      height: 0,
      componentCheck: 0,
      fixed: true,
      addproduct: false,
      tableData: [],
      search: "",
      selectStatusType: "ALL",
      SnackBarComponent: {},
      productitems: {},
      tableLoading: false,
      toggle_exclusive: "edit_product",
      rowInfo: {},
      deleteProductDialog: false,
      headers: [{
        text: "Name",
        value: "product_name",
        sortable: false
      }, {
        text: "Description",
        value: "product_description",
        sortable: false
      }, {
        text: "Created On",
        value: "product_created_on",
        sortable: false
      }, {
        text: "Created By",
        value: "product_created_by",
        sortable: false
      }, {
        text: "Industries Type",
        value: "industries_type",
        sortable: false
      }, {
        text: "Owned By",
        value: "product_head",
        sortable: false
      }, {
        text: "#Campaings",
        value: "no_of_campaigns",
        sortable: false
      }, {
        text: "Action",
        value: "Actions",
        sortable: false
      }]
    };
  },
  watch: {
    search() {
      if (this.search != "") {
        if (this.search.length >= 3) {
          this.get_product();
        }
      } else {
        this.get_product();
      }
    }
    // nextToken() {
    //   this.updatePagination();
    // },
  },
  mounted() {
    this.get_product();
  },
  created() {
    this.height = window.innerHeight - 310;
    this.$store.commit("Setproductitems", {});
  },
  methods: {
    back_mutation() {
      this.displayedit = false;
    },
    delete_product(item) {
      this.componentCheck = 2;
      this.deleteProductDialog = true;
      this.rowInfo = item;
    },
    filter_data() {
      this.tableData = [];
      this.get_product();
    },
    handle_row_click(item) {
      this.productitems = item;
      this.$store.commit("Setproductitems", this.productitems);
      this.$router.push("ViewProduct");
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addproduct = false;
      this.deleteProductDialog = false;
      this.get_product();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    createproductdailog() {
      this.componentCheck = 1;
      this.addproduct = true;
    },
    get_date(date) {
      let a = new Date(date * 1000).toLocaleTimeString("en-In", {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit"
      });
      return a.toUpperCase();
    },
    async get_product() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_product_details, {
          input: {
            organization_id: data.organization.organization_id,
            limit: 100,
            nextToken: null,
            industries_type: this.selectStatusType
          }
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.list_product_details);
        if (response.Status == "SUCCESS") {
          this.tableLoading = false;
          this.tableData = response.data;
        } else {
          this.tableLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
